<?php
declare(strict_types=1);
require_once __DIR__.'/StaySchema.php';
require_once __DIR__.'/Schedule.php';
final class Transport
{
    private static function text(mixed $v,int $min,int $max):string{if(!is_string($v)||str_contains($v,"\0"))throw new HttpError(400,'Thông tin chuyến xe không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);$n=$v===null?-1:strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($n<$min||$n>$max)throw new HttpError(400,'Kiểm tra độ dài thông tin chuyến xe.');return $v;}
    private static function number(mixed $v,int $min,int $max):int{if(!is_int($v)||$v<$min||$v>$max)throw new HttpError(400,'Số khách hoặc thời gian nhận chuyến không hợp lệ.');return $v;}
    private static function time(mixed $v):string{if(!is_string($v)||!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$v))throw new HttpError(400,'Giờ đón/trả không hợp lệ.');return $v;}
    public static function config(mixed $v):array{if(!is_array($v)||array_diff(array_keys($v),['mode','origin','destination','leadMinutes'])||!in_array($v['mode']??null,['PRIVATE','SHARED'],true))throw new HttpError(400,'Cấu hình dịch vụ xe không hợp lệ.');return ['mode'=>$v['mode'],'origin'=>self::text($v['origin']??null,2,200),'destination'=>self::text($v['destination']??null,2,200),'leadMinutes'=>self::number(array_key_exists('leadMinutes',$v)?$v['leadMinutes']:60,0,10080)];}
    public static function trip(mixed $v):array
    {
        if(!is_array($v)||array_diff(array_keys($v),['pickup','dropoff','pickupTime','passengers','flightNumber','returnDate','returnTime']))throw new HttpError(400,'Thông tin chuyến xe không hợp lệ.');$out=['pickup'=>self::text($v['pickup']??null,3,300),'dropoff'=>self::text($v['dropoff']??null,3,300),'pickupTime'=>self::time($v['pickupTime']??null),'passengers'=>self::number($v['passengers']??null,1,150),'flightNumber'=>self::text(array_key_exists('flightNumber',$v)?$v['flightNumber']:'',0,40)];if(array_key_exists('returnDate',$v))$out['returnDate']=StaySchema::date($v['returnDate']);if(array_key_exists('returnTime',$v))$out['returnTime']=self::time($v['returnTime']);return $out;
    }
    public static function validateTrip(array $p,string $variantId,string $date,?string $slotId,array $quantities,?array $trip,?int $now=null):?array
    {
        if(!isset($p['transport'])){if($trip!==null)throw new HttpError(400,'Sản phẩm này không phải dịch vụ xe.');return null;}$config=self::config($p['transport']);$info=self::trip($trip);$variant=null;foreach($p['variants'] as $v)if($v['id']===$variantId)$variant=$v;if(!$variant)throw new HttpError(400,'Loại xe không tồn tại.');$units=$quantities['ADULT']??0;foreach($quantities as $g=>$n)if($g!=='ADULT'&&$n)throw new HttpError(400,'Xe chỉ tính theo số chuyến hoặc số chỗ.');if($units<1)throw new HttpError(400,'Chọn số chuyến hoặc số chỗ.');if($config['mode']==='PRIVATE'&&($units!==1||$info['passengers']>($variant['maxPassengers']??1)))throw new HttpError(400,'Mỗi dòng đặt một xe, số khách không vượt sức chứa.');
        if($config['mode']==='SHARED'){$slots=Schedule::slots($variant,$date);$slot=null;foreach($slots as $s)if($s['id']===$slotId)$slot=$s;if(!$slot&&count($slots)===1)$slot=$slots[0];if(!$slot||$slot['start']!==$info['pickupTime']||$info['passengers']!==$units)throw new HttpError(400,'Xe ghép: số khách bằng số chỗ, giờ đón đúng suất.');}
        $departure=(new DateTimeImmutable($date.' '.$info['pickupTime'].':00',new DateTimeZone('Asia/Ho_Chi_Minh')))->getTimestamp();if($departure<=($now??time())+$config['leadMinutes']*60)throw new HttpError(400,'Đã qua hạn nhận chuyến. Chọn ngày/giờ khác.');$round=$variant['roundTrip']??false;if($round){if(!isset($info['returnDate'],$info['returnTime'])||(new DateTimeImmutable($info['returnDate'].' '.$info['returnTime'].':00',new DateTimeZone('Asia/Ho_Chi_Minh')))->getTimestamp()<=$departure)throw new HttpError(400,'Chọn ngày giờ về sau chuyến đi.');}elseif(isset($info['returnDate'])||isset($info['returnTime']))throw new HttpError(400,'Gói một chiều không có chuyến về.');$extra=['mode'=>$config['mode'],'origin'=>$config['origin'],'destination'=>$config['destination']];if(array_key_exists('maxPassengers',$variant))$extra['maxPassengers']=$variant['maxPassengers'];$extra['roundTrip']=$round;return $info+$extra;
    }
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public function list(array $in):array
    {
        if(array_diff(array_keys($in),['date','page']))throw new HttpError(400,'Bộ lọc điều xe không hợp lệ.');$date=array_key_exists('date',$in)?StaySchema::date($in['date']):null;$v=$in['page']??1;if(array_key_exists('page',$in)&&!is_string($v)&&!is_int($v)||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)$v)||(int)$v>100000)throw new HttpError(400,'Trang không hợp lệ.');$args=$date?[$date]:[];$where=$date?' WHERE j.visit_date=?':'';
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{$total=(int)$this->query('SELECT COUNT(*) FROM jingo_transport_jobs j'.$where,$args)->fetchColumn();$page=min((int)$v,max(1,(int)ceil($total/30)));$rows=$this->query('SELECT j.*,o.code,o.snapshot,o.contact,o.booking_status,o.payment_status FROM jingo_transport_jobs j JOIN jingo_orders o ON o.id=j.order_id'.$where.' ORDER BY j.visit_date DESC,j.order_id LIMIT 30 OFFSET '.(($page-1)*30),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){foreach(['data','snapshot','contact'] as $key)$r[$key]=json_decode($r[$key],true,512,JSON_THROW_ON_ERROR);$r['version']=(int)$r['version'];}unset($r);$this->db->commit();return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>30];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function save(string $id,array $in,string $actor):array
    {
        if(!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id)||count($in)!==7||array_diff(array_keys($in),['version','status','driver','phone','plate','operator','note'])||!is_int($in['version']??null)||$in['version']<1||$in['version']>2147483646||!in_array($in['status']??null,['PENDING','ASSIGNED','RUNNING','COMPLETED'],true))throw new HttpError(400,'Thông tin điều xe không hợp lệ.');$data=[];foreach(['driver'=>120,'phone'=>25,'plate'=>30,'operator'=>150,'note'=>1000] as $k=>$max)$data[$k]=self::text($in[$k]??null,0,$max);if($in['status']!=='PENDING'&&($data['driver']===''||$data['plate']===''||!preg_match('/^\+?[0-9 ()-]{8,25}$/D',$data['phone'])))throw new HttpError(400,'Điền tài xế, điện thoại và biển số.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{$order=$this->query('SELECT booking_status FROM jingo_orders WHERE id=? FOR UPDATE',[$id])->fetchColumn();$job=$this->query('SELECT status,version FROM jingo_transport_jobs WHERE order_id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if($order===false||!$job)throw new HttpError(404,'Không tìm thấy chuyến.');if($order!=='CONFIRMED')throw new HttpError(409,'Đơn đã hủy hoặc chưa xác nhận.');if((int)$job['version']!==$in['version'])throw new HttpError(409,'Chuyến vừa thay đổi. Tải lại.');$next=['PENDING'=>['PENDING','ASSIGNED'],'ASSIGNED'=>['PENDING','ASSIGNED','RUNNING'],'RUNNING'=>['RUNNING','COMPLETED'],'COMPLETED'=>[]];if(!in_array($in['status'],$next[$job['status']]??[],true))throw new HttpError(409,'Không thể chuyển trạng thái này.');$this->query('UPDATE jingo_transport_jobs SET status=?,data=?,version=version+1 WHERE order_id=?',[$in['status'],json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'transport.'.strtolower($in['status']),$id]);$this->db->commit();return ['ok'=>true];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
